function wait(ms, signal) {
  return new Promise((resolve, reject) => {
    const id = setTimeout(() => resolve("done"), ms);
    signal.addEventListener("abort", () => {
      clearTimeout(id);
      reject(new Error("aborted"));
    });
  });
}

const c = new AbortController();
wait(50, c.signal).then(console.log, (e) => console.log(e.message));
setTimeout(() => c.abort(), 10);

const fakeSearch = (q, ms) =>
  new Promise((r) => setTimeout(() => r("results for " + q), ms));

let latest = 0;
let shown = "";

async function search(q, ms) {
  const id = ++latest;
  const result = await fakeSearch(q, ms);
  if (id === latest) shown = result;
}

search("re", 30);
search("react", 10);
setTimeout(() => console.log(shown), 50);
